import json, os

def parse_mtx(path):
    with open(path) as f:
        lines = f.readlines()
    header = lines[0].strip().lower()
    symmetric = 'symmetric' in header
    data_lines = [l.strip() for l in lines[1:] if not l.startswith('%') and l.strip()]
    rows, cols, declared = map(int, data_lines[0].split())
    entries = data_lines[1:]
    if len(entries) != declared:
        return rows, cols, declared, None, symmetric
    coords = {}
    for e in entries:
        r, c, v = e.split()
        r, c, v = int(r)-1, int(c)-1, float(v)
        coords[(r,c)] = coords.get((r,c), 0.0) + v
    if symmetric:
        extra = {}
        for (r,c), v in coords.items():
            if r != c:
                extra[(c,r)] = extra.get((c,r), 0.0) + v
        for k, v in extra.items():
            coords[k] = coords.get(k, 0.0) + v
    coords = {k: v for k, v in coords.items() if v != 0.0}
    return rows, cols, declared, coords, symmetric

manifest = json.load(open('/app/manifest.json'))
results = []

for job in manifest['jobs']:
    mid = job['id']
    mpath = '/app/' + job['matrix']
    vpath = '/app/' + job['vector']
    vec = json.load(open(vpath))

    try:
        rows, cols, declared, coords, _ = parse_mtx(mpath)
        shape = [rows, cols]
    except Exception:
        results.append({'id': mid, 'status': 'invalid', 'reason': 'entry-count-mismatch', 'shape': None, 'nnz_after_coalesce': 0, 'y': []})
        continue

    if coords is None:
        results.append({'id': mid, 'status': 'invalid', 'reason': 'entry-count-mismatch', 'shape': shape, 'nnz_after_coalesce': 0, 'y': []})
        continue

    if len(vec) != cols:
        results.append({'id': mid, 'status': 'invalid', 'reason': 'dimension-mismatch', 'shape': shape, 'nnz_after_coalesce': 0, 'y': []})
        continue

    y = [0.0] * rows
    for (r, c), v in coords.items():
        y[r] += v * vec[c]

    results.append({
        'id': mid,
        'status': 'ok',
        'reason': 'ok',
        'shape': shape,
        'nnz_after_coalesce': len(coords),
        'y': [round(v, 6) for v in y]
    })

out = {'matrices': results}
with open('/app/matrix-report.json', 'w') as f:
    f.write(json.dumps(out, indent=2) + '\n')

